class Solution:
    def combinationSum4(self, nums: List[int], target: int) -> int:
        dp = [0] * (target + 1)
        dp[0] = 1
        for total in range(1, target + 1):
            ways = 0
            for x in nums:
                if x > total:
                    continue
                ways += dp[total - x]
            dp[total] = ways
        return dp[target]

