public class Main {
    static int[] parseIntArray(String s) {
        int l = s.indexOf('[');
        int r = s.lastIndexOf(']');
        String body = s.substring(l + 1, r).trim();
        if (body.isEmpty()) return new int[0];
        String[] parts = body.split(",");
        int[] a = new int[parts.length];
        for (int i = 0; i < parts.length; i++) a[i] = Integer.parseInt(parts[i].trim());
        return a;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        int firstOpen = line.indexOf('[');
        int firstClose = line.indexOf(']', firstOpen);
        String numsText = line.substring(firstOpen + 1, firstClose + 1);
        int comma = line.indexOf(',', firstClose);
        int target = Integer.parseInt(line.substring(comma + 1, line.lastIndexOf(']')).trim());
        int[] nums = parseIntArray(numsText);
        System.out.println(new Solution().combinationSum4(nums, target));
    }
}

